// This file is generated by AI.

// 应用级全屏补正。
//
// 任何元素进入全屏（预览 iframe、资源预览视频、导出成片播放器……）都会成为顶层文档的
// `fullscreenElement`；Windows 上 Tauri 会把它映射成窗口全屏。问题出在“最大化窗口 + 无边框
// 全屏”这个组合：tao 进入全屏时不清最大化状态，客户端区停在任务栏之上的工作区大小，底部
// 留下一条任务栏高的黑边。
//
// 这里监听一次全局 `fullscreenchange`，复用 `preview/fullscreen.ts` 的状态机与动作顺序；
// 所有媒体控件因此共用同一套补正，不需要每个 `<video>` 各写一遍。

import { getCurrentWindow } from '@tauri-apps/api/window';

import {
  applyPreviewFullscreenAction,
  previewFullscreenTransition,
  type PreviewFullscreenStatus,
} from '../preview/fullscreen';

let installed = false;
let dispose: (() => void) | null = null;

/**
 * 安装全局全屏补正；重复调用返回同一个清理函数。
 *
 * 在浏览器（非 Tauri）里拿不到窗口时静默跳过，不影响元素全屏本身。
 */
export function installFullscreenCorrection(): () => void {
  if (installed && dispose !== null) return dispose;

  let win: ReturnType<typeof getCurrentWindow>;
  try {
    win = getCurrentWindow();
  } catch {
    return () => {};
  }

  let status: PreviewFullscreenStatus = { mirrored: false, corrected: false };
  let windowWasMaximized = false;

  /*
   * 只在**不在全屏**时记录窗口形态：全屏那一次的 resize 正是要修的形态变化，不能拿它当
   * “用户想要的窗口样子”。resize 可能早于或晚于 `fullscreenchange`，两种顺序都对。
   */
  const syncWindowWasMaximized = () => {
    if (document.fullscreenElement !== null) return;
    void win
      .isMaximized()
      .then((value) => {
        windowWasMaximized = value;
      })
      .catch(() => {});
  };

  const onFullscreenChange = () => {
    const next = previewFullscreenTransition(status, {
      fullscreenActive: document.fullscreenElement !== null,
      windowWasMaximized,
    });
    status = { mirrored: next.mirrored, corrected: next.corrected };
    void applyPreviewFullscreenAction(win, next.action).catch((error) => {
      // 窗口侧失败不该影响元素全屏：只是窗口形态可能不对。
      console.error('全屏补正失败', error);
    });
  };

  syncWindowWasMaximized();
  const unlistenResize = win.onResized(syncWindowWasMaximized);
  document.addEventListener('fullscreenchange', onFullscreenChange);

  installed = true;
  dispose = () => {
    document.removeEventListener('fullscreenchange', onFullscreenChange);
    void unlistenResize.then((off) => off());
    // 应用退出/热重载时元素全屏可能已经被摘掉，那份 fullscreenchange 未必还能听到。
    if (status.corrected) {
      void applyPreviewFullscreenAction(win, { kind: 'restore-maximized' }).catch(() => {});
    }
    installed = false;
    dispose = null;
  };
  return dispose;
}
